// Server-side password gate for /milton-finance-review.
// A password-only login form issues an httpOnly session cookie; the dashboard
// HTML is base64-embedded here and only returned to authenticated requests.
// There is no client-side password check and no public static copy, so nothing
// is exposed by "View Source" or by guessing an asset URL before logging in.

const PASSWORD = "DashboardGoddard91@";
const COOKIE = "milton_auth";
const TOKEN = "c0a8603890a07e2b7b40700ccd86738ff798e5fe9f727bc6cdd60e28511be2b0"; // server-side session secret; only issued after a correct password
const HTML_B64 = "";

function loginPage(error) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Milton Finance Review — Private</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:"Iowan Old Style","Palatino Linotype",Palatino,"Book Antiqua",Georgia,"Times New Roman",serif;
    background:#f4f1ea;color:#20262b;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;-webkit-font-smoothing:antialiased}
  .box{width:100%;max-width:380px;background:#fff;border:1px solid #e2ddd1;border-radius:8px;
    padding:38px 32px;box-shadow:0 1px 2px rgba(40,35,25,.05),0 10px 30px rgba(40,35,25,.06);text-align:center}
  .eyebrow{font-size:11px;letter-spacing:2.4px;text-transform:uppercase;color:#9a7b34;font-weight:600}
  h1{font-size:23px;font-weight:600;margin:8px 0 4px;letter-spacing:-.2px}
  p.sub{color:#6a7178;font-style:italic;font-size:14px;margin-bottom:22px}
  input[type=password]{width:100%;padding:12px 14px;font-size:16px;font-family:inherit;
    border:1px solid #d8d2c4;border-radius:6px;background:#faf9f5;color:#20262b;margin-bottom:14px}
  input[type=password]:focus{outline:none;border-color:#2f6b4f;box-shadow:0 0 0 3px rgba(47,107,79,.12)}
  button{width:100%;padding:12px 14px;font-size:15px;font-family:inherit;font-weight:600;
    border:none;border-radius:6px;background:#2f6b4f;color:#fff;cursor:pointer;letter-spacing:.3px}
  button:hover{background:#27583f}
  .err{color:#9c3a34;font-size:13px;font-style:italic;margin-bottom:14px}
</style></head>
<body>
  <form class="box" method="POST" action="/milton-finance-review">
    <div class="eyebrow">Private</div>
    <h1>Milton Finance Review</h1>
    <p class="sub">Enter the password to continue.</p>
    ${error ? `<div class="err">${error}</div>` : ""}
    <input type="password" name="password" placeholder="Password" autofocus autocomplete="current-password" required>
    <button type="submit">View</button>
  </form>
</body></html>`;
}

function hasValidCookie(req) {
  const h = req.headers.cookie || "";
  const m = h.match(/(?:^|;\s*)milton_auth=([^;]+)/);
  return m && m[1] === TOKEN;
}

function readBody(req) {
  return new Promise((resolve) => {
    let b = "";
    req.on("data", (c) => { b += c; if (b.length > 1e6) req.destroy(); });
    req.on("end", () => resolve(b));
    req.on("error", () => resolve(""));
  });
}

function sendDashboard(res) {
  res.statusCode = 200;
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "private, no-store");
  res.setHeader("X-Robots-Tag", "noindex, nofollow");
  res.end(Buffer.from(HTML_B64, "base64").toString("utf8"));
}

module.exports = async (req, res) => {
  if (req.method === "POST") {
    let pw = "";
    if (req.body && typeof req.body === "object" && "password" in req.body) {
      pw = req.body.password;
    } else {
      const raw = (req.body && typeof req.body === "string") ? req.body : await readBody(req);
      pw = new URLSearchParams(raw).get("password") || "";
    }
    if (pw === PASSWORD) {
      // POST-redirect-GET so a refresh doesn't re-submit the form
      res.statusCode = 303;
      res.setHeader("Set-Cookie", `${COOKIE}=${TOKEN}; HttpOnly; Secure; SameSite=Lax; Path=/milton-finance-review; Max-Age=43200`);
      res.setHeader("Location", "/milton-finance-review");
      res.setHeader("Cache-Control", "no-store");
      res.end();
      return;
    }
    res.statusCode = 401;
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.setHeader("Cache-Control", "no-store");
    res.end(loginPage("Incorrect password. Please try again."));
    return;
  }

  // GET
  if (hasValidCookie(req)) { sendDashboard(res); return; }
  res.statusCode = 200;
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Cache-Control", "no-store");
  res.setHeader("X-Robots-Tag", "noindex, nofollow");
  res.end(loginPage(""));
};
